-- generated by tools/gencatalog, do not edit by hand

CREATE TABLE org_units (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    code VARCHAR(64) NOT NULL,
    name VARCHAR(128) NOT NULL,
    kind TEXT CHECK (kind IN ('DEPARTMENT', 'TEAM')) NOT NULL,
    parent_id BIGINT REFERENCES org_units(id),
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE org_unit_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    org_unit_id BIGINT       NOT NULL REFERENCES org_units(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_org_unit_revisions_revision
        UNIQUE (org_unit_id, revision_number)
);

CREATE UNIQUE INDEX uq_org_units_code
    ON org_units (code);

CREATE INDEX idx_org_units_parent_id
    ON org_units (parent_id);

CREATE INDEX idx_org_units_active
    ON org_units (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_org_unit_revisions_org_unit_id
    ON org_unit_revisions (org_unit_id);

CREATE INDEX idx_org_unit_revisions_covering_agg
    ON org_unit_revisions (org_unit_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_org_unit_revisions_changed_at
    ON org_unit_revisions (changed_at);

CREATE INDEX idx_org_units_parent ON org_units (parent_id) WHERE is_deleted = FALSE;

CREATE OR REPLACE VIEW v_expanded_org_unit AS
SELECT
    t.id,
    t.code,
    t.name,
    t.kind,
    t.parent_id,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM org_units t
LEFT JOIN (
    SELECT
        org_unit_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM org_unit_revisions
    GROUP BY org_unit_id
) agg ON agg.org_unit_id = t.id;

COMMENT ON TABLE org_units IS
    'Organizational units: departments and teams with their hierarchy. Stores the current state of each record.';

COMMENT ON TABLE org_unit_revisions IS
    'Immutable audit log of changes applied to org_units. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_org_unit IS
    'Read-only view that enriches each org_unit with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
